Table(
    {Value: "Book a Bus", Icon:ImgCreateDisabled , IconSelected:ImgCreateSelected, Screen: App.ActiveScreen},
    {Value: "Bookings", Icon:ImgBookingDisabled, IconSelected:ImgBookingSelected, Screen: App.ActiveScreen},
    {Value: "Buses", Icon: ImgCarDisabled, IconSelected:ImgCarSelected,Screen: App.ActiveScreen},
    {Value: "My Bookings", Icon: ImgHistoryDisabled, IconSelected:ImgHistorySelected,Screen: App.ActiveScreen}
   
 )

Set(CurrentUser, Blank());
Set(IsAdminUser, false);
Navigate(HomeScreen, ScreenTransition.Fade);

Table(
    {Value: "Book a Bus", Icon:ImgCreateDisabled , IconSelected:ImgCreateSelected, Screen: App.ActiveScreen},
    {Value: "Bookings", Icon:ImgBookingDisabled, IconSelected:ImgBookingSelected, Screen: App.ActiveScreen},
    {Value: "Buses", Icon: ImgCarDisabled, IconSelected:ImgCarSelected,Screen: App.ActiveScreen},
    {Value: "My Bookings", Icon: ImgHistoryDisabled, IconSelected:ImgHistorySelected,Screen: App.ActiveScreen}
   
 )

If(
    IsBlank(Txt_CarName_4.Text) || IsBlank(Txt_CarID_4.Text),
    
    // Show error message if required fields are empty
    UpdateContext({
        ShowError: true
    }),

    // Clear error and proceed with patching
    UpdateContext({
        ShowError: false,
        ShowLoader: true // Show loader while processing
    });

    // Patch the Title, CarID, CarStatus, and CarAddedDate columns
    Set(
        PatchedItem,
        Patch(
            'Booking pCars List',
            Defaults('Booking pCars List'), // Or the specific item if updating
            {
                Title: Txt_CarName.Text, // Patching the car name
                CarID: Value(Txt_CarID.Text), // Patching the car ID
                CarStatus: {
                    '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedReference",
                    Value: "Active" // Patching the CarStatus Choice column with 'Active'
                },
                CarAddedDate: Today() // Patching the CarAddedDate column with the current date
            }
        )
    );

    // Submit the form to handle attachments for the patched item
    // Ensure the form is linked to the same SharePoint list item by setting its Item property
    If(
        Not(IsBlank(PatchedItem)), // Check if patching was successful
        AttachmentForm.LastSubmit.ID = PatchedItem.ID; // Link the attachment form to the patched item
        SubmitForm(AttachmentForm);  // Submit the attachment form
    );

    // Reset all input controls
    Reset(Txt_CarName); // Reset the Car Name input
    Reset(Txt_CarID);   // Reset the Car ID input
    Reset(AddAttachment); // Replace with the name of your individual attachment control

    // Set success message and hide loader
    UpdateContext({
        SuccessMessage: "Booking information successfully updated.", // Show success message
        ShowLoader: false, // Hide loader
        AddCarPopup: false // Close the popup after submission
    })
);
ClearCollect(BookingpCarCollection,'Booking pCars List')

Filter(
    Table(
        {Value: "Home", Icon: mm, IconSelected: mm, Screen: Home1, RequiresAdmin: false},
        {Value: "Projects", Icon: projects, IconSelected: ImgHistorySelected, Screen: AI, RequiresAdmin: false},
        {Value: "LL by risk analysis", Icon: ImgBookingDisabled, IconSelected: ImgBookingSelected, Screen: Booking, RequiresAdmin: false},
        {Value: "Add LL by risk analysis", Icon: ImgCarDisabled, IconSelected: ImgCarSelected, Screen: Create, RequiresAdmin: true},
        {Value: "Processes", Icon: img1, IconSelected: ImgCreateSelected, Screen: proo, RequiresAdmin: false},
        {Value: "Fault catalog", Icon: ImgBookingDisabled, IconSelected: ImgBookingSelected, Screen: Bookingp, RequiresAdmin: false},
        {Value: "Add Lesson by process", Icon: addlesson, IconSelected: ImgCarSelected, Screen: Createp, RequiresAdmin: true}
    ),
    // La condition de filtrage :
    !RequiresAdmin || (RequiresAdmin && !IsBlank(CurrentUser) && IsAdminUser)
)

