    ),
    // La condition de filtrage :
    !RequiresAdmin || (RequiresAdmin && !IsBlank(CurrentUser) && IsAdminUser)
)

Set(CurrentUser, Blank());
Set(IsAdminUser, false);
Navigate(HomeScreen, ScreenTransition.Fade);

Filter(
    Table(
        {Value: "Home", Icon: mm, IconSelected: mm, Screen: Home1, RequiresAdmin: false},
        {Value: "Projects", Icon: projects, IconSelected: ImgHistorySelected, Screen: AI, RequiresAdmin: false},
        {Value: "LL by risk analysis", Icon: ImgBookingDisabled, IconSelected: ImgBookingSelected, Screen: Booking, RequiresAdmin: false},
        {Value: "Add LL by risk analysis", Icon: ImgCarDisabled, IconSelected: ImgCarSelected, Screen: Create, RequiresAdmin: true},
        {Value: "Processes", Icon: img1, IconSelected: ImgCreateSelected, Screen: proo, RequiresAdmin: false},
        {Value: "Fault catalog", Icon: ImgBookingDisabled, IconSelected: ImgBookingSelected, Screen: Bookingp, RequiresAdmin: false},
        {Value: "Add Lesson by process", Icon: addlesson, IconSelected: ImgCarSelected, Screen: Createp, RequiresAdmin: true}
    ),
    // La condition de filtrage :
    !RequiresAdmin || (RequiresAdmin && !IsBlank(CurrentUser) && IsAdminUser)
)

Filter(
    Table(
        {Value: "Home", Icon: mm, IconSelected: mm, Screen: Home1, RequiresAdmin: false},
        {Value: "Projects", Icon: projects, IconSelected: ImgHistorySelected, Screen: AI, RequiresAdmin: false},
        {Value: "LL by PROJECT", Icon: ImgBookingDisabled, IconSelected: ImgBookingSelected, Screen: Booking, RequiresAdmin: false},
        {Value: "Add LL by PROJECT", Icon: ImgCarDisabled, IconSelected: ImgCarSelected, Screen: Create, RequiresAdmin: true},
        {Value: "Processes", Icon: img1, IconSelected: ImgCreateSelected, Screen: proo, RequiresAdmin: false},
        {Value: "Fault catalog", Icon: ImgBookingDisabled, IconSelected: ImgBookingSelected, Screen: Bookingp, RequiresAdmin: false},
        {Value: "Add LL by PROCESS", Icon: addlesson, IconSelected: ImgCarSelected, Screen: Createp, RequiresAdmin: true}
    ),
    // La condition de filtrage :
    !RequiresAdmin || (RequiresAdmin && !IsBlank(CurrentUser) && IsAdminUser)
)

Set(
    SelectedMonth,
    MonthDropDown_1.Selected.MonthNumber
);

ClearCollect(
    CalendarDays,
    ForAll(
        Sequence(
            Date(Year(Today()), SelectedMonth + 1, 1) - Date(Year(Today()), SelectedMonth, 1)
        ),
        {
            DayNumber: Value,
            DayDate: Date(Year(Today()), SelectedMonth, Value),
            DayName: Text(Date(Year(Today()), SelectedMonth, Value), "dddd"),
            IsToday: Date(Year(Today()), SelectedMonth, Value) = Today(),
            IsDisabled: Or(
                Date(Year(Today()), SelectedMonth, Value) < Today(),
                Weekday(Date(Year(Today()), SelectedMonth, Value)) = 1,
                Weekday(Date(Year(Today()), SelectedMonth, Value)) = 7
            )
        }
    )
);

// Add Empty Days before the 1st of the Month
ClearCollect(
    CalendarWithBlanks,
    ForAll(
        Sequence(Weekday(Date(Year(Today()), SelectedMonth, 1), StartOfWeek.Sunday) - 1),
        {
            DayNumber: Blank(),
            DayDate: Blank(),
            DayName: Blank(),
            IsToday: false,
            IsDisabled: true
        }
    )
);

// Merge Empty Days with the Actual Calendar Days
Collect(CalendarWithBlanks, CalendarDays);

// Reset SelectedDate to today if we're in the current month
If(
    Month(Today()) = SelectedMonth && Year(Today()) = Year(Today()),
    Set(SelectedDate, Today())
);
Reset(CalenderGallery);

If(
    IsBlank(CalenderGallery_1.Selected.DayNumber), 
    // Show notification if no pick-up time is selected
    Notify("No pick-up Day has been selected. Please select another date", NotificationType.Error),
Reset(TimeGallery_starttime_1);
Reset(TimeGallery_EndTime__1);
UpdateContext({CurrentView : "ViewCars"});
)

If(
    Not(IsBlank(LookUp(SelectedUsers, Mail = ThisItem.Mail))),
    Notify("User already added!", NotificationType.Warning),
    Collect(SelectedUsers, {
        DisplayName: ThisItem.DisplayName,
        Mail: ThisItem.Mail
    });
    UpdateContext({CurrentView: "ViewOccupant"})
)

// ✅ Afficher le loader
UpdateContext({ShowLoader: true});

// ✅ Patch : ajout ou modification
Set(
    PatchedItem5,
    Patch(
        'Booking pList',
        If(IsBlank(varItemToEdit), Defaults('Booking pList'), varItemToEdit),
        {
            BookingPurpose: {
                '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedReference",
                Value: GalleryPurposeofBooking_1.Selected.Value
            },
            BookedCarID: GalleryAvaliableCars_1.Selected.CarID,
            BookedCarName: GalleryAvaliableCars_1.Selected.Title,
            BookingPickupLocation: TxtPickUpLocation_1.Text,
            BookingDropoffLocation: TxtDropoffLocation_1.Text,
            BookingDropoffLocation2: TxtDropoffLocation_2.Text,
            Requestor: {
                '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
                Claims: "i:0#.f|membership|" & Lower(Office365Users.MyProfile().Mail),
                DisplayName: Office365Users.MyProfile().DisplayName,
                Email: Office365Users.MyProfile().Mail,
                Department: Office365Users.MyProfile().Department,
                JobTitle: Office365Users.MyProfile().JobTitle,
                Picture: Office365Users.UserPhotoV2(Office365Users.MyProfile().Mail)
            },
            BookingDate: CalenderGallery.Selected.DayDate,
           
            BookingOccupants: If(
                IsEmpty(SelectedUsers),
                Blank(),
                ForAll(
                    SelectedUsers,
                    {
                        '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
                        Claims: "i:0#.f|membership|" & Lower(ThisRecord.Mail),
                        DisplayName: ThisRecord.DisplayName,
                        Email: ThisRecord.Mail,
                        Department: Office365Users.UserProfile(ThisRecord.Mail).Department,
                        Picture: Office365Users.UserPhotoV2(ThisRecord.Mail),
                        JobTitle: Office365Users.UserProfile(ThisRecord.Mail).JobTitle
                    }
                )
            ),
            BookingStatus: {
                '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedReference",
                Value: "Positive Lesson"
            }
        }
    )
);

// ✅ Vérifier le succès
If(
    !IsBlank(PatchedItem5) && !IsError(PatchedItem5),
    
    Notify("Lesson saved with Success !", NotificationType.Success);

    // ✅ Nettoyer les champs
    Clear(SelectedUsers);
    Reset(TxtPickUpLocation_1);
    Reset(TxtDropoffLocation_1);
    Reset(TxtDropoffLocation_2);
    Reset(AddAttachment_6);
    Reset(GalleryPurposeofBooking_1);
    Reset(GalleryAvaliableCars_1);
    Reset(CalenderGallery);
    Reset(TimeGallery_starttime);
    Reset(TimeGallery_EndTime_);

    // ✅ Réinitialiser le contexte
    UpdateContext({
        ShowLoader: false,
        EmptyFields: false,
        CurrentView: "ViewSuccess"
    });

    // ✅ Réinitialiser varItemToEdit pour pouvoir refaire un ajout
    Set(varItemToEdit, Blank());

    // ✅ Recharger les données
    ClearCollect(BookingpListCollection, 'Booking pList')
    
;);

// Setting the Default time to the next available time that is not disabled
If(
    DateValue(CalenderGallery_1.Selected.DayDate) = Today(),
    {Time: DefaultAvailableTime},
    {Time: TimeValue("08:00 AM")}
)

// Check if the selected time should be disabled based on several conditions
If(
    // Condition 1: Disable if the selected time is 04:30 PM or 05:00 PM
    Text(ThisItem.Time, "hh:mm AM/PM") = "04:30 PM" || 
    Text(ThisItem.Time, "hh:mm AM/PM") = "05:00 PM" ||

    // Condition 2: Disable if the selected day is today AND the time is earlier than the current time
    (
        DateValue(CalenderGallery_1.Selected.DayDate) = Today() && // Check if the selected day is today
        TimeValue(Text(ThisItem.Time, "hh:mm AM/PM")) <= TimeValue(Text(Now(), "hh:mm AM/PM")) // Compare time values
    ),

    // If any condition is true, disable the time slot
    DisplayMode.Disabled,

    // Otherwise, allow editing (time slot is available)
    DisplayMode.Edit
)

// Check if a pick-up time is selected
If(
    IsBlank(TimeGallery_starttime_1.Selected.Time), 
    // Show notification if no pick-up time is selected
    Notify("No pick-up time has been selected. Please select another date", NotificationType.Error),

    // Otherwise, proceed with the logic
    UpdateContext({ShowSearch:true}); // Proceed to search

    // Load the cars into a collection
    ClearCollect(BookingpCarCollection, 'Booking pCars List');

    // Load Booking List as well as into a collection first
    ClearCollect(
        BookingpListCollection,
        'Booking pList'
    );

    // Collect conflicting bookings using the local collection
    ClearCollect(
        ConflictingBookings,
        Filter(
            BookingpListCollection, BookingStatus.Value <> "Cancelled" &&
            BookingDate = CalenderGallery_1.Selected.DayDate && 
            
            (
                (
                    TimeValue(Text(TimeGallery_starttime_1.Selected.Time, "[$-en-US]hh:mm:ss AM/PM")) >= TimeValue(BookingPickUpTime) &&
                    TimeValue(Text(TimeGallery_starttime_1.Selected.Time, "[$-en-US]hh:mm:ss AM/PM")) < TimeValue(BookingDropOffTime)
                ) ||
                (
                    TimeValue(Text(TimeGallery_EndTime__1.Selected.Time, "[$-en-US]hh:mm:ss AM/PM")) > TimeValue(BookingPickUpTime) &&
                    TimeValue(Text(TimeGallery_EndTime__1.Selected.Time, "[$-en-US]hh:mm:ss AM/PM")) <= TimeValue(BookingDropOffTime)
                ) ||
                (
                    TimeValue(Text(TimeGallery_starttime_1.Selected.Time, "[$-en-US]hh:mm:ss AM/PM")) <= TimeValue(BookingPickUpTime) &&
                    TimeValue(Text(TimeGallery_EndTime__1.Selected.Time, "[$-en-US]hh:mm:ss AM/PM")) >= TimeValue(BookingDropOffTime)
                )
            )
        )
    );

    // Update context variables
    UpdateContext({ShowSearch: false});
    UpdateContext({CurrentView: "ViewCars"});
    UpdateContext({CarLoader: true})
)
